#include "my_hw/my_system_interface.hpp"

#include <limits>
#include <string>
#include <vector>

#include "hardware_interface/types/hardware_interface_type_values.hpp"
#include "rclcpp/rclcpp.hpp"

namespace my_hw
{

hardware_interface::CallbackReturn MySystemInterface::on_init(
  const hardware_interface::HardwareInfo & info)
{
  if (
    hardware_interface::SystemInterface::on_init(info) !=
    hardware_interface::CallbackReturn::SUCCESS)
  {
    return hardware_interface::CallbackReturn::ERROR;
  }

  hw_position_commands_.resize(info_.joints.size(), 0.0);
  hw_position_states_.resize(info_.joints.size(), 0.0);
  hw_velocity_states_.resize(info_.joints.size(), 0.0);

  for (const hardware_interface::ComponentInfo & joint : info_.joints)
  {
    if (joint.command_interfaces.size() != 1)
    {
      RCLCPP_FATAL(
        rclcpp::get_logger("MySystemInterface"),
        "Joint '%s' has %zu command interfaces found. 1 expected.",
        joint.name.c_str(), joint.command_interfaces.size());
      return hardware_interface::CallbackReturn::ERROR;
    }

    if (joint.command_interfaces[0].name != hardware_interface::HW_IF_POSITION)
    {
      RCLCPP_FATAL(
        rclcpp::get_logger("MySystemInterface"),
        "Joint '%s' has %s command interface found. '%s' expected.",
        joint.name.c_str(), joint.command_interfaces[0].name.c_str(),
        hardware_interface::HW_IF_POSITION);
      return hardware_interface::CallbackReturn::ERROR;
    }

    if (joint.state_interfaces.size() != 2)
    {
      RCLCPP_FATAL(
        rclcpp::get_logger("MySystemInterface"),
        "Joint '%s' has %zu state interfaces found. 2 expected.",
        joint.name.c_str(), joint.state_interfaces.size());
      return hardware_interface::CallbackReturn::ERROR;
    }
  }

  return hardware_interface::CallbackReturn::SUCCESS;
}

std::vector<hardware_interface::StateInterface> MySystemInterface::export_state_interfaces()
{
  std::vector<hardware_interface::StateInterface> state_interfaces;
  for (std::size_t i = 0; i < info_.joints.size(); ++i)
  {
    state_interfaces.emplace_back(
      info_.joints[i].name, hardware_interface::HW_IF_POSITION, &hw_position_states_[i]);
    state_interfaces.emplace_back(
      info_.joints[i].name, hardware_interface::HW_IF_VELOCITY, &hw_velocity_states_[i]);
  }
  return state_interfaces;
}

std::vector<hardware_interface::CommandInterface> MySystemInterface::export_command_interfaces()
{
  std::vector<hardware_interface::CommandInterface> command_interfaces;
  for (std::size_t i = 0; i < info_.joints.size(); ++i)
  {
    command_interfaces.emplace_back(
      info_.joints[i].name, hardware_interface::HW_IF_POSITION, &hw_position_commands_[i]);
  }
  return command_interfaces;
}

hardware_interface::CallbackReturn MySystemInterface::on_activate(
  const rclcpp_lifecycle::State & /*previous_state*/)
{
  for (std::size_t i = 0; i < hw_position_states_.size(); ++i)
  {
    hw_position_states_[i] = 0.0;
    hw_velocity_states_[i] = 0.0;
    hw_position_commands_[i] = hw_position_states_[i];
  }

  RCLCPP_INFO(rclcpp::get_logger("MySystemInterface"), "Hardware activated.");

  return hardware_interface::CallbackReturn::SUCCESS;
}

hardware_interface::CallbackReturn MySystemInterface::on_deactivate(
  const rclcpp_lifecycle::State & /*previous_state*/)
{
  RCLCPP_INFO(rclcpp::get_logger("MySystemInterface"), "Hardware deactivated.");
  return hardware_interface::CallbackReturn::SUCCESS;
}

hardware_interface::return_type MySystemInterface::read(
  const rclcpp::Time & /*time*/, const rclcpp::Duration & /*period*/)
{
  // Real hardware would read sensor feedback here. This is exposed via
  // hw_position_states_ / hw_velocity_states_, which are updated in write()
  // once the simulated actuators have integrated the latest command.
  return hardware_interface::return_type::OK;
}

hardware_interface::return_type MySystemInterface::write(
  const rclcpp::Time & /*time*/, const rclcpp::Duration & period)
{
  const double dt = period.seconds();
  for (std::size_t i = 0; i < hw_position_commands_.size(); ++i)
  {
    const double previous_position = hw_position_states_[i];
    hw_position_states_[i] = hw_position_commands_[i];
    hw_velocity_states_[i] =
      dt > std::numeric_limits<double>::epsilon()
      ? (hw_position_states_[i] - previous_position) / dt
      : 0.0;
  }
  return hardware_interface::return_type::OK;
}

}  // namespace my_hw

#include "pluginlib/class_list_macros.hpp"

PLUGINLIB_EXPORT_CLASS(my_hw::MySystemInterface, hardware_interface::SystemInterface)

